  | { type: "selectCell"; cell: number }
  | { type: "cycle" }
  | { type: "undo" }
  | { type: "clear" }
export type PackAudit = {
  certified: true
  solutionCount: number
  solutionMeaning: string
  unique: boolean
  nodes: number
  foothold: { cell: number; value: number; reason: string } | null
  solution: (number | null)[]
}

